// Provided infrastructure — do not modify.
public sealed class CjStubHandler : HttpMessageHandler
{
    private readonly System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<HttpResponseMessage>> _script;
    private readonly System.Collections.Generic.Dictionary<string, int> _next = new();
    private readonly bool _record;
    private readonly bool _data;

    public static HttpRequestMessage? LastRequest { get; private set; }
    public static System.Collections.Generic.List<int> Delays { get; } = new();
    public static int HandlerCount { get; private set; }

    public CjStubHandler(System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<HttpResponseMessage>> script, bool record = false, bool data = false)
    {
        _script = script; _record = record; _data = data;
        HandlerCount++;
    }

    public static System.Collections.Generic.List<HttpResponseMessage> One(HttpResponseMessage resp) => new() { resp };
    public static System.Collections.Generic.List<HttpResponseMessage> Sequence(params HttpResponseMessage[] items) => new(items);
    public static System.Collections.Generic.List<HttpResponseMessage> Always(HttpResponseMessage resp) => new() { resp, resp, resp, resp, resp, resp, resp, resp };
    public static HttpResponseMessage Json(int code, string body) =>
        new((HttpStatusCode)code) { Content = new StringContent(body) };

    // One client per test: stub handler + base address, ready to use.
    public static HttpClient Client(System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<HttpResponseMessage>> script) =>
        new(new CjStubHandler(script)) { BaseAddress = new System.Uri("https://api.test") };
    public static HttpClient Recording() =>
        new(new CjStubHandler(new System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<HttpResponseMessage>>(), record: true)) { BaseAddress = new System.Uri("https://api.test") };
    public static HttpClient Default() =>
        new(new CjStubHandler(new System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<HttpResponseMessage>>(), data: true)) { BaseAddress = new System.Uri("https://api.test") };

    // Deterministic fake delay: records the requested delay, does not sleep.
    public static Task DelayAsync(int milliseconds, CancellationToken ct)
    {
        Delays.Add(milliseconds);
        return Task.CompletedTask;
    }

    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage req, CancellationToken ct)
    {
        LastRequest = CloneRequest(req);   // snapshot: HttpClient disposes the original after send
        string path = req.RequestUri!.PathAndQuery;
        if (_data)
            return Task.FromResult(Json(200, "data:" + path.TrimStart('/')));
        if (_script.TryGetValue(path, out var list))
        {
            int i = _next.TryGetValue(path, out int n) ? n : 0;
            _next[path] = System.Math.Min(i + 1, list.Count - 1);
            return Task.FromResult(Clone(list[i]));   // fresh instance per send — a sent response is disposed
        }
        return Task.FromResult(Json(404, ""));
    }

    private static HttpResponseMessage Clone(HttpResponseMessage source)
    {
        var copy = new HttpResponseMessage(source.StatusCode);
        foreach (var h in source.Headers) copy.Headers.TryAddWithoutValidation(h.Key, h.Value);
        if (source.Content is not null)
            copy.Content = new StringContent(
                source.Content.ReadAsStringAsync(CancellationToken.None).GetAwaiter().GetResult());
        return copy;
    }

    private static HttpRequestMessage CloneRequest(HttpRequestMessage source)
    {
        var copy = new HttpRequestMessage(source.Method, source.RequestUri);
        foreach (var h in source.Headers) copy.Headers.TryAddWithoutValidation(h.Key, h.Value);
        if (source.Content is not null)
        {
            string body = source.Content.ReadAsStringAsync(CancellationToken.None).GetAwaiter().GetResult();
            var media = source.Content.Headers.ContentType?.MediaType ?? "application/octet-stream";
            copy.Content = new StringContent(body, System.Text.Encoding.UTF8, media);
        }
        return copy;
    }
}

